<script setup lang="ts">
import { useCourseDonations, type CourseDonation } from '~/composables/useCourseDonations'
definePageMeta({ layout: 'main', middleware: 'auth' })
const { fetchMyDonations } = useCourseDonations(); const rows = ref<CourseDonation[]>([]); const meta = ref<any>({}); const loading = ref(true)
const load = async (page = 1) => { loading.value = true; try { const response = await fetchMyDonations({ page }); rows.value = response.data; meta.value = response.meta } finally { loading.value = false } }
onMounted(() => load()); const money = (row: CourseDonation) => row.donation_type === 'point' ? `${row.points_amount ?? 0} points` : `${row.cash_amount ?? 0} ${row.currency || 'THB'}`
</script>
<template><div class="mx-auto max-w-6xl space-y-6 p-6"><div><h1 class="text-2xl font-bold text-slate-900 dark:text-white">Course donations</h1><p class="text-sm text-slate-500">Your support history</p></div><div class="overflow-hidden rounded-2xl bg-white shadow-sm dark:bg-slate-800"><table class="w-full text-left text-sm"><thead class="bg-slate-50 dark:bg-slate-700"><tr><th class="p-4">Date</th><th class="p-4">Course</th><th class="p-4">Type</th><th class="p-4">Amount</th><th class="p-4">Status</th><th class="p-4">Purpose</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="p-8 text-center">Loading…</td></tr><tr v-else-if="!rows.length"><td colspan="6" class="p-12 text-center text-slate-500">No donations yet.</td></tr><tr v-for="row in rows" :key="row.id" class="border-t dark:border-slate-700"><td class="p-4">{{ new Date(row.created_at).toLocaleDateString() }}</td><td class="p-4"><NuxtLink v-if="row.course" :to="`/Learn/Courses/${row.course.id}`" class="text-primary-600">{{ row.course.name }}</NuxtLink><span v-else>Course #{{ row.course_id }}</span></td><td class="p-4"><span class="rounded-full bg-slate-100 px-2 py-1 text-xs">{{ row.donation_type }}</span></td><td class="p-4">{{ money(row) }}</td><td class="p-4"><span class="rounded-full bg-indigo-50 px-2 py-1 text-xs text-indigo-700">{{ row.status }}</span></td><td class="max-w-xs truncate p-4">{{ row.purpose || '—' }}</td></tr></tbody></table></div><div class="flex justify-center gap-3"><button v-if="meta.current_page > 1" class="rounded-lg border px-3 py-2" @click="load(meta.current_page - 1)">Previous</button><span class="p-2">{{ meta.current_page || 1 }}</span><button v-if="meta.current_page < meta.last_page" class="rounded-lg border px-3 py-2" @click="load(meta.current_page + 1)">Next</button></div></div></template>
